import numpy as np
from scipy.optimize import minimize

def objective(x):
    p, q, r, s = x
    return (p + s) * (r + q) - (p * s + q * r)

def constraint(x):
    return x

# Try to minimize the absolute value of the objective
res = minimize(lambda x: abs(objective(x)), [1.0, 1.0, 1.0, 1.0], bounds=[(1e-6, 100)]*4)
print(res.fun, res.x)

import numpy as np
from scipy.optimize import minimize_scalar

def E(x):
    return 1/x + x + (x-2)/(2*x-1) + (2*x-1)/(x-2)

res = minimize_scalar(E, bounds=(2.0001, 100), method='bounded')
print(res.fun, res.x)
